def det_input(b: int, c: int, t: int) -> Tensor:
    vals = List[float](capacity=b * c * t)
    for i in range(b):
        for j in range(c):
            for k in range(t):
                vals.append(math.sin(0.05 * k * (j + 1) + i) + 0.1 * math.cos(0.3 * k + j))
    return torch.tensor(vals, dtype=torch.float32).reshape(b, c, t)

